var cc = tree.root.get_node("Main").charge_controller
var out = []
for i in range(cc.unit_selector.get_item_count()):
	out.append(str(cc.unit_selector.get_item_metadata(i)))
return ",".join(out)

var cc = tree.root.get_node("Main").charge_controller
var out = []
for i in cc.target_list.get_selected_items():
	out.append(str(cc.target_list.get_item_metadata(i)))
return ",".join(out)

